function n(id, title, category, level, parent, summary, points, source, why, tags=[]) { return {id,title,category,level,parent,summary,points,source,why,tags}; }
const NODES = [
  n('atlas','JavaScript Engineering','core','foundation',null,'The language is only the center. Mastery means understanding the browser, servers, data, security, delivery, and the trade-offs connecting them.',['Learn in dependency order, then revisit through project work.','Prefer durable mental models over memorizing library APIs.'], 'mdn','This is the root of every path.'),
  n('js','JavaScript language','core','foundation','atlas','JavaScript is a dynamic, garbage-collected language standardized as ECMAScript. The same core language runs in browsers, servers, and many tools.',['Values have types; variables hold values.','Execution is single-threaded per agent, with concurrency coordinated by host APIs.'],'spec','Everything else executes or transforms JavaScript.'),
  n('values','Values & types','core','foundation','js','JavaScript has primitive values—string, number, bigint, boolean, undefined, symbol, and null—and objects. Operators may coerce values, sometimes surprisingly.',['Use === unless coercion is intentional.','null is deliberate absence; undefined usually means missing.'],'mdn','Correct programs start with a precise model of values.'),
  n('control','Control flow','core','foundation','js','Conditionals choose a path; loops repeat work; functions package decisions. Exceptions interrupt normal flow and should represent exceptional failure.',['Prefer small, named functions.','Return early to keep the main path visible.'],'mdn','Makes behavior explicit and testable.'),
  n('objects','Objects & prototypes','core','builder','js','Objects are property collections linked to another object called a prototype. Classes are cleaner syntax over this prototype system, not a separate object model.',['Own and inherited properties differ.','Composition often stays simpler than deep class inheritance.'],'spec','Framework state and most APIs are objects.'),
  n('functions','Functions & closures','core','builder','js','Functions are values. A closure is a function plus access to the lexical environment where it was created—even after that outer function returns.',['Closures power callbacks, modules, and private state.','this is set by call form; arrow functions capture it lexically.'],'mdn','A foundational model for events and asynchronous code.'),
  n('modules','Modules','core','builder','js','ES modules give files explicit imports and exports. Their bindings are live, evaluated once, and form a dependency graph.',['Use named exports for discoverability.','Cycles work but often signal tangled design.'],'mdn','The unit of reuse for browsers, Node, and bundlers.'),
  n('async','Async & event loop','core','builder','js','Promises represent future completion. async/await is promise syntax. The host event loop schedules tasks; promise reactions run as microtasks before the next task.',['Await independent work together with Promise.all.','Cancellation needs an explicit signal such as AbortSignal.'],'mdn','Prevents frozen interfaces and slow, serial servers.'),
  n('memory','Memory & performance','core','senior','js','Garbage collection frees unreachable objects, not objects you forgot you still reference. Performance work starts with measurement, realistic workloads, and algorithmic costs.',['Release event listeners and bounded caches.','Optimize the measured bottleneck, not intuition.'],'mdn','Leaks and long tasks become production incidents.'),
  n('metaprogramming','Iterators, generators & proxies','core','mastery','js','Protocols such as iteration let objects participate in language features. Generators pause and resume computation; proxies intercept fundamental object operations.',['Protocols compose better than one-off conventions.','Proxy magic has debugging and performance costs.'],'spec','Useful for libraries, lazy streams, and framework internals.'),

  n('web','The browser platform','web','foundation','atlas','A browser parses HTML, applies CSS, runs JavaScript, loads resources, enforces security boundaries, and exposes Web APIs.',['HTML gives meaning, CSS presentation, JavaScript behavior.','Progressive enhancement keeps core tasks resilient.'],'html','Frontend engineering begins with the platform.'),
  n('dom','DOM & events','web','foundation','web','The DOM is the in-memory tree of a document. Events travel through capture, target, and bubble phases, enabling delegation from stable ancestors.',['Change classes or attributes instead of scattered inline styles.','Use semantic controls before recreating them.'],'mdn','Every UI framework ultimately updates this platform.'),
  n('css','CSS systems','web','builder','web','CSS resolves competing declarations through origin, importance, layers, specificity, and source order. Layout systems—flow, flexbox, and grid—solve different spatial problems.',['Design tokens centralize shared decisions.','Container queries make components respond to available space.'],'css','Robust interfaces depend on predictable layout.'),
  n('a11y','Accessibility','web','builder','web','Accessibility means people with different bodies, senses, devices, and situations can complete the same tasks. Semantics, keyboard access, focus, names, and contrast are core engineering constraints.',['Start with native HTML semantics.','Test with keyboard and screen-reader workflows.'],'a11y','Inclusive products are also more resilient products.'),
  n('network','HTTP & the network','web','builder','web','HTTP is a stateless request–response protocol. Methods express intent, status codes express outcomes, and headers control caching, negotiation, credentials, and security.',['GET should be safe; PUT and DELETE should be idempotent.','Caching is correctness plus performance, not an afterthought.'],'http','Every web boundary depends on these semantics.'),
  n('storage','Browser storage','web','builder','web','Cookies travel with requests; Web Storage is synchronous string storage; IndexedDB is asynchronous structured storage. Each has different lifetime and security properties.',['Keep secrets out of browser-readable storage.','Design migration and quota failure paths.'],'mdn','Offline behavior and sessions require deliberate storage.'),
  n('workers','Workers, PWA & offline','web','senior','web','Web Workers move computation off the UI thread. Service workers intercept network requests and enable offline caches, background behavior, and installable experiences.',['Workers communicate by messages, not shared DOM.','Cache invalidation needs versioning and recovery.'],'sw','Enables responsive computation and resilient apps.'),
  n('rendering','Rendering performance','web','senior','web','Browsers parse, style, lay out, paint, and composite. User experience depends on loading speed, input responsiveness, and visual stability—not just bundle size.',['Avoid forced synchronous layout.','Measure Core Web Vitals with field data.'],'webperf','Speed is part of product quality.'),
  n('wasm','WebAssembly','web','mastery','web','WebAssembly is a compact, sandboxed instruction format designed as a compilation target. JavaScript remains the usual glue to browser and host capabilities.',['Use it for measured CPU-heavy workloads.','Boundary crossings and deployment add complexity.'],'wasm','Expands the web stack beyond JavaScript workloads.'),

  n('ts','TypeScript','types','foundation','atlas','TypeScript checks JavaScript programs before they run, then erases its types. It does not validate data at runtime.',['Types describe possible values and relationships.','Compiler strictness prevents whole bug classes.'],'ts','Makes large codebases easier to change safely.'),
  n('tsfund','Inference & narrowing','types','builder','ts','Type inference avoids redundant annotations. Narrowing uses runtime checks—such as typeof, equality, or discriminants—to prove a value is more specific.',['Model absence explicitly.','Prefer unknown over any at untrusted boundaries.'],'ts','Turns control flow into trustworthy type information.'),
  n('generics','Generics & type design','types','senior','ts','Generics preserve relationships between inputs and outputs. Unions model alternatives; intersections combine requirements; mapped and conditional types transform shapes.',['Expose the smallest useful type surface.','Discriminated unions make invalid states harder to represent.'],'ts','Essential for reusable APIs and libraries.'),
  n('runtime-types','Runtime validation','types','senior','ts','Network, storage, and user input arrive without trustworthy types. Parse them with schemas or explicit checks, then operate on validated domain values.',['Validation should return useful error structure.','Derive static types from schemas when practical.'],'ts','Static types stop at process boundaries.'),

  n('frontend','Frontend engineering','front','builder','atlas','Frontend architecture coordinates state, rendering, navigation, data fetching, accessibility, and performance around user tasks.',['Use the platform directly until abstraction earns its cost.','Organize by product capability, not file extension.'],'mdn','Turns web primitives into maintainable products.'),
  n('components','Components & state','front','builder','frontend','Components bind a coherent piece of interface to inputs, local state, and events. State should have one clear owner and be derived rather than duplicated.',['Separate server state from temporary UI state.','Keep state as local as its consumers allow.'],'react','A durable model shared across UI frameworks.'),
  n('react','React','front','builder','components','React describes UI as a function of props and state. Rendering must stay pure; effects synchronize with systems outside React.',['Keys identify list items across renders.','You might not need an effect if a value can be derived.'],'react','A representative component runtime and ecosystem.'),
  n('vue-angular','Vue & Angular','front','builder','components','Vue uses reactive templates and a progressively adoptable model. Angular is an opinionated application framework with dependency injection, routing, forms, and tooling included.',['Choose based on team and product constraints.','Learn their reactivity and rendering models, not only syntax.'],'vue','Shows the major alternative framework philosophies.'),
  n('routing','Routing & forms','front','builder','frontend','Routing maps URLs to application state; forms collect, validate, and submit data. Both should preserve browser conventions such as history, links, labels, and native submission.',['URLs are shareable state.','Validate on client for experience and server for trust.'],'html','Core workflows should survive refreshes and errors.'),
  n('data-ui','Fetching & server state','front','senior','frontend','Remote data has loading, success, stale, empty, and error states. Caches coordinate deduplication, revalidation, optimistic changes, and invalidation.',['Give every request an error and cancellation path.','Invalidate by domain event, not arbitrary timeout alone.'],'http','Most complex UI bugs are data lifecycle bugs.'),
  n('ssr','SSR, SSG & islands','front','senior','frontend','Server rendering creates HTML per request; static generation creates it ahead of time; islands hydrate only interactive regions. Each trades freshness, cost, complexity, and interactivity.',['Choose rendering per route, not ideology.','Hydration requires server and client output to agree.'],'next','Shapes performance, hosting, and data boundaries.'),
  n('design-systems','Design systems','front','senior','frontend','A design system combines tokens, components, patterns, accessibility rules, and governance. It is a shared product language, not merely a component package.',['Build around real repeated needs.','Document behavior, states, and content—not only props.'],'a11y','Lets teams scale consistent, accessible UI.'),

  n('tooling','Toolchain & packages','craft','builder','atlas','Package managers resolve and install dependencies; build tools transform modules and assets; linters and formatters automate rules and consistency.',['Commit a lockfile.','Keep the pipeline understandable and reproducible.'],'npm','Modern development depends on a trustworthy supply chain.'),
  n('bundlers','Bundlers & Vite','craft','builder','tooling','Bundlers trace a module graph and emit deployable assets. Vite serves native modules during development and uses an optimized production build.',['Code-split at meaningful boundaries.','Inspect output before chasing tiny configuration wins.'],'vite','Explains what happens between source and browser.'),
  n('testing','Testing strategy','craft','builder','atlas','Tests buy confidence. Unit tests isolate logic; integration tests exercise cooperating parts; end-to-end tests cover critical user journeys.',['Test observable behavior over implementation details.','Use a smaller number of slower, broader tests.'],'testing','Makes refactoring and delivery safer.'),
  n('e2e','Browser testing','craft','senior','testing','Browser tests automate real rendering, navigation, and input. Stable tests use user-visible roles and outcomes, controlled data, and useful traces on failure.',['Avoid arbitrary sleeps.','Cover critical journeys, not every permutation.'],'playwright','Catches failures unit tests cannot see.'),
  n('git','Git & collaboration','craft','foundation','atlas','Git stores a graph of snapshots. Branches are movable labels; merges join histories; rebase copies commits onto a new base.',['Make small commits with an intent.','Review for correctness, clarity, risk, and learning.'],'git','Engineering is collaborative change management.'),

  n('backend','Backend JavaScript','back','builder','atlas','Backend systems turn authenticated requests and events into durable business outcomes. Boundaries, failure handling, observability, and data integrity matter more than framework syntax.',['Keep transport, domain logic, and persistence separable.','Assume networks and dependencies fail.'],'node','Extends the language into services and automation.'),
  n('node','Node.js runtime','back','builder','backend','Node runs JavaScript on V8 and exposes non-blocking I/O through its event loop. CPU-heavy work blocks a process unless moved to workers or other services.',['Stream large data instead of buffering it all.','Handle shutdown and rejected work deliberately.'],'node','The dominant server runtime in the ecosystem.'),
  n('runtimes','Deno, Bun & edge','back','senior','backend','Deno and Bun offer alternative runtimes and toolchains; edge runtimes run near users with restricted APIs. Compatibility, cold starts, resources, and deployment model differ.',['Target capabilities, not marketing labels.','Verify Node API and package compatibility.'],'deno','Helps choose a runtime from constraints.'),
  n('api','REST & API design','back','builder','backend','A good HTTP API models resources, uses protocol semantics, validates input, returns consistent errors, and evolves without surprising clients.',['Paginate collections and bound inputs.','Make retries safe with idempotency where needed.'],'openapi','APIs are long-lived contracts between teams and systems.'),
  n('graphql','GraphQL','back','senior','backend','GraphQL lets clients request typed fields through one schema. Resolvers assemble results, while batching and query limits control cost.',['Schema design is product API design.','Prevent N+1 queries and unbounded operations.'],'graphql','Useful where clients need flexible, connected data.'),
  n('realtime','Realtime & messaging','back','senior','backend','WebSockets provide a long-lived two-way channel; server-sent events stream server updates; queues decouple producers from consumers. Delivery may be duplicated or reordered.',['Define ordering and retry guarantees.','Make consumers idempotent.'],'http','Distributed coordination requires explicit guarantees.'),
  n('jobs','Background jobs','back','senior','backend','Jobs move slow or retryable work outside request latency. A durable queue, bounded retries, backoff, idempotency, and a dead-letter path make failure manageable.',['Store business state before enqueueing dependent work.','Expose job status when users care about completion.'],'twelve','Turns fragile long requests into reliable workflows.'),

  n('database','Data systems','data','builder','atlas','Data design starts with access patterns, integrity, scale, and failure needs—not database fashion. Every persistence choice makes trade-offs.',['Let the database enforce durable invariants.','Measure with production-shaped data.'],'postgres','Most products are really data systems with interfaces.'),
  n('sql','Relational modeling & SQL','data','builder','database','Relational databases organize facts into tables with keys and constraints. SQL declares the result you need; the optimizer chooses an execution plan.',['Normalize first; denormalize for measured needs.','Use transactions for multi-step invariants.'],'sql','A durable foundation for business data.'),
  n('indexes','Indexes & query plans','data','senior','sql','An index stores selected values in a structure optimized for lookup and ordering. It speeds reads but costs memory, storage, and write work.',['Inspect EXPLAIN plans.','Create indexes for real predicates, joins, and ordering.'],'postgres','Performance requires knowing how queries execute.'),
  n('transactions','Transactions & concurrency','data','senior','sql','Transactions group changes atomically. Isolation levels control anomalies when operations overlap; locks and optimistic checks coordinate competing writers.',['Keep transactions short.','Retry serialization failures safely.'],'postgres','Protects correctness under concurrency.'),
  n('nosql','Documents, key-value & cache','data','senior','database','Document stores keep aggregate-shaped records; key-value stores optimize direct lookup; caches trade freshness and complexity for speed.',['Design from access patterns.','A cache needs ownership, invalidation, and failure behavior.'],'mongo','Broadens the storage toolbox without abandoning rigor.'),
  n('migrations','Migrations & backups','data','senior','database','Schema changes are production changes. Safe migrations are backward compatible across rolling deploys; backups matter only if restores are tested.',['Expand, migrate, then contract.','Define recovery point and recovery time objectives.'],'postgres','Data outlives application versions.'),
  n('distributed-data','Replication & consistency','data','mastery','database','Replication improves availability and read scale but introduces lag and failure decisions. Distributed systems cannot guarantee every desirable property during partitions.',['Choose consistency from business invariants.','Design for duplicate, delayed, and missing messages.'],'postgres','Mastery means reasoning clearly about failure.'),

  n('auth','Identity & authorization','security','builder','atlas','Authentication proves who is acting. Authorization decides what that identity may do. Sessions preserve this context across requests.',['Enforce authorization on every trusted boundary.','Deny by default and grant narrowly.'],'owasp','Identity mistakes expose real user data.'),
  n('sessions','Sessions, cookies & tokens','security','builder','auth','Cookie sessions keep an opaque identifier in a protected cookie. Tokens carry claims but are not automatically safer and are harder to revoke.',['Use Secure, HttpOnly, and suitable SameSite cookies.','Rotate session identifiers after privilege changes.'],'owasp','The storage and transport model defines the threat surface.'),
  n('oauth','OAuth 2.0 & OIDC','security','senior','auth','OAuth delegates access to an API; OpenID Connect adds identity. Authorization code with PKCE protects public clients. Validate issuer, audience, signature, nonce, and state as applicable.',['Never invent an auth protocol.','Use maintained libraries and provider discovery.'],'oauth','Needed for federated login and delegated access.'),
  n('passkeys','Passkeys & WebAuthn','security','senior','auth','WebAuthn uses origin-bound public-key credentials. Passkeys can replace passwords with phishing-resistant sign-in while the server stores no reusable secret.',['Plan account recovery and device changes.','Verify ceremonies on the server.'],'webauthn','The modern direction for safer authentication.'),
  n('appsec','Web threat model','security','builder','atlas','Threat modeling identifies assets, trust boundaries, attackers, and abuse paths before selecting controls. XSS, CSRF, injection, broken access control, and SSRF are recurring web risks.',['Treat every external value as untrusted.','Encode for the output context and parameterize queries.'],'owasp','Security begins with models, not checklists.'),
  n('browser-sec','Browser security & CSP','security','senior','appsec','The same-origin policy isolates sites. CORS relaxes read access; it is not authorization. CSP constrains where active content can load and limits XSS impact.',['Prefer nonce- or hash-based strict CSP.','Do not reflect arbitrary origins with credentials.'],'csp','Browser controls are powerful when used for their actual purpose.'),
  n('secrets','Secrets & cryptography','security','senior','appsec','Secrets belong in managed secret storage, never source or client bundles. Cryptographic design is easy to get wrong; use established protocols and high-level libraries.',['Hash passwords with a password-specific algorithm and unique salts.','Plan rotation and audit access.'],'crypto','A leaked or misused key can bypass every other control.'),
  n('supply-chain','Supply-chain security','security','senior','tooling','Dependencies execute with your trust during build or runtime. Reduce the graph, pin resolution, review updates, protect publishing, and generate provenance where available.',['Audit reachability, not severity counts alone.','Use least-privilege CI credentials.'],'npm','Modern applications inherit the risk of their dependencies.'),

  n('ops','Delivery & operations','ops','builder','atlas','Production engineering makes change repeatable, observable, reversible, and boring. Environments should differ through configuration rather than ad hoc code.',['Automate checks and deployment.','Prefer small changes with fast feedback.'],'twelve','Software creates value only when it runs reliably.'),
  n('ci','CI/CD','ops','builder','ops','Continuous integration validates each change in a reproducible environment. Continuous delivery keeps a releasable artifact; deployment releases it to users.',['Run fast deterministic checks first.','Promote one built artifact across environments.'],'twelve','Shortens the path from idea to safe feedback.'),
  n('containers','Containers & orchestration','ops','senior','ops','Containers package a process and filesystem; they do not replace architecture. Orchestrators schedule, restart, network, and configure many workloads.',['Use minimal non-root images.','Set resource requests, limits, and health checks.'],'docker','Standardizes execution and scaling.'),
  n('cloud','Cloud & serverless','ops','senior','ops','Cloud services trade operational control for managed capabilities. Serverless bills and scales around requests or events, with limits on duration, state, startup, and environment.',['Design for stateless compute and external durable state.','Model cost under realistic traffic.'],'cloudflare','Architecture must fit the execution environment.'),
  n('observability','Logs, metrics & traces','ops','senior','ops','Logs explain events, metrics show trends, and traces connect work across boundaries. Shared context and structured fields turn telemetry into evidence.',['Instrument user-visible outcomes and dependencies.','Never log secrets or unnecessary personal data.'],'otel','You cannot operate what you cannot understand.'),
  n('reliability','Reliability engineering','ops','mastery','ops','Reliability is a product feature expressed through service-level indicators, objectives, and error budgets. Timeouts, bounded retries, circuit breakers, and load shedding limit cascading failure.',['Retry only transient, idempotent work with jitter.','Practice incident response and learn without blame.'],'otel','Connects architecture to real service quality.'),

  n('architecture','Software architecture','architecture','senior','atlas','Architecture is the set of decisions that are expensive to change. Good boundaries align with business capabilities, information ownership, and team responsibility.',['Start modular before distributing.','Record important decisions and their context.'],'twelve','Senior engineers optimize systems and organizations, not files.'),
  n('patterns','Patterns & principles','architecture','senior','architecture','Patterns name recurring trade-offs; principles such as cohesion, coupling, and dependency direction help evaluate them. Names are tools for conversation, not laws.',['Prefer high cohesion and explicit dependencies.','Choose the simplest design that protects expected change.'],'mdn','Enables deliberate design without cargo cults.'),
  n('distributed','Distributed systems','architecture','mastery','architecture','Across a network, latency is variable, messages can be lost or duplicated, clocks disagree, and partial failure is normal. Every abstraction eventually exposes these facts.',['Set deadlines and propagate cancellation.','Use idempotency keys and durable state transitions.'],'twelve','The core mental model for resilient services.'),
  n('leadership','Technical leadership','craft','mastery','architecture','Mastery includes turning ambiguity into shared decisions, raising team capability, managing risk, and balancing product, people, and technology over time.',['Write clearly: context, options, decision, consequences.','Mentor through questions, feedback, and meaningful ownership.'],'git','Senior impact is multiplied through other people.'),
  n('product','Product & systems thinking','craft','mastery','architecture','Engineering choices exist inside user, business, legal, and operational systems. The best solution solves the real constraint and measures the intended outcome.',['Clarify the user problem before selecting technology.','Treat privacy, accessibility, and operations as product requirements.'],'a11y','Prevents excellent execution on the wrong problem.')
];

