const STUDY = {
  values:{model:'A variable is a label; the value is the thing. Primitives behave like copied values, while object variables copy a reference to the same object.',example:'let a = {score: 1}; let b = a; b.score = 2; // a.score is now 2',practice:'Predict ten expressions involving null, undefined, ==, ===, &&, ||, and ??. Then verify them in the console.',check:'Why can changing b affect a for objects but not for numbers?'},
  functions:{model:'A closure is retained access, not a frozen snapshot. The function keeps the bindings from the scope where it was created.',example:'function counter(){ let n=0; return () => ++n } const next=counter(); // 1, then 2',practice:'Build a once(fn) helper that calls fn only the first time and returns the cached result later.',check:'What exactly stays alive after counter returns, and why?'},
  objects:{model:'Property lookup starts on the object, then follows its prototype chain. class syntax creates constructor and prototype relationships for you.',example:'const child=Object.create({role:"reader"}); child.name="Ada"; // role is inherited',practice:'Use Object.hasOwn to separate own properties from inherited ones, then reproduce the same relationship with class syntax.',check:'Where is a method declared in a class stored: each instance or its prototype?'},
  modules:{model:'A module is evaluated once and exposes live bindings. Importers observe later changes to exported bindings; they do not receive copied snapshots.',example:'export let count=0; export const inc=()=>count++; // importers observe count changing',practice:'Split a small program into domain, persistence, and UI modules. Make every dependency visible as an import.',check:'Why can a circular import observe a binding before it is initialized?'},
  async:{model:'JavaScript finishes the current call stack first. Promise callbacks enter the microtask queue; timers enter a task queue. Microtasks drain before the next task.',example:'console.log(1); Promise.resolve().then(()=>console.log(2)); setTimeout(()=>console.log(3)); // 1,2,3',practice:'Fetch three independent URLs concurrently, cancel them with one AbortController, and show partial failures.',check:'Why does awaiting three requests one after another take longer than Promise.all?'},
  memory:{model:'Reachability—not usefulness—controls garbage collection. A cache, listener, timer, or closure can accidentally keep a large object graph reachable.',example:'window.addEventListener("resize", handler); // remove it when the owning component is disposed',practice:'Create and fix a listener leak, then compare heap snapshots or repeated allocation in browser developer tools.',check:'Why can a WeakMap avoid retaining keys that an ordinary Map would keep alive?'},
  dom:{model:'The DOM is a mutable tree. Events travel down during capture and back up during bubbling, so one ancestor can manage many changing children.',example:'list.addEventListener("click", e => e.target.closest("button")?.remove())',practice:'Build a keyboard-accessible todo list using one delegated click listener on the list.',check:'When should you use event.currentTarget instead of event.target?'},
  css:{model:'CSS is constraint resolution. The cascade chooses values; layout algorithms then solve sizes and positions from the containing context.',example:'.cards { display:grid; grid-template-columns:repeat(auto-fit,minmax(16rem,1fr)) }',practice:'Create the same responsive card row with Grid and Flexbox. Write down which constraint each expresses better.',check:'Which wins first: cascade layer order or selector specificity?'},
  a11y:{model:'Accessible UI exposes correct name, role, value, state, focus order, and interaction through platform semantics.',example:'<button aria-expanded="false" aria-controls="menu">Topics</button>',practice:'Complete one full workflow using only the keyboard, then inspect names and roles in the accessibility tree.',check:'Why is a styled div with an onclick handler not equivalent to a button?'},
  network:{model:'HTTP messages describe intent and representation. Caches and intermediaries can participate because methods, status codes, and headers have shared semantics.',example:'ETag: "v7" → client sends If-None-Match → server may answer 304 without a body',practice:'Design responses for create, validation failure, missing resource, conflict, rate limit, and unexpected failure.',check:'What is the difference between a safe method and an idempotent method?'},
  tsfund:{model:'TypeScript follows runtime control flow. Every successful check removes impossible members from a union inside that branch.',example:'if (typeof value === "string") value.toUpperCase(); // narrowed to string',practice:'Replace an any input with unknown and narrow it using a reusable type guard.',check:'Why does a type assertion provide less safety than a narrowing check?'},
  generics:{model:'A useful generic preserves a relationship. T is valuable when the same unknown type appears in two or more meaningful positions.',example:'function first<T>(xs: T[]): T | undefined { return xs[0] }',practice:'Type a pluck(objects, key) function so its return type changes with the selected key.',check:'When is a concrete union clearer than introducing a generic parameter?'},
  'runtime-types':{model:'Static types describe code you control; parsing establishes trust at runtime. Validation should transform unknown input into a known domain value.',example:'const result = UserSchema.safeParse(JSON.parse(body)); if (!result.success) return 400',practice:'Write a schema for one API payload, including nested errors, defaults, and an invalid-date case.',check:'Why cannot a TypeScript interface validate JSON received over the network?'},
  components:{model:'A component is a boundary with inputs, owned state, derived values, and emitted events. Duplicate state creates synchronization work and bugs.',example:'const total = items.reduce(sum,0) // derive it; do not keep a second total state',practice:'Take a large form and draw which component owns each value before writing code.',check:'How can you tell whether state should move up, stay local, or move to server cache?'},
  react:{model:'Render calculates UI from current inputs. Effects run afterward to synchronize with something outside React—not to calculate ordinary derived data.',example:'const fullName = `${first} ${last}` // no effect or extra state required',practice:'Remove one unnecessary effect from an app and replace it with rendering logic or an event handler.',check:'Why can an effect run more than once in development, and what bug is that trying to reveal?'},
  'data-ui':{model:'Server state is a time-stamped local belief about remote truth. Fetching needs explicit states plus a policy for freshness, retry, and invalidation.',example:'Optimistically update UI → send mutation → confirm or roll back → invalidate related query keys',practice:'Implement a mutation that rolls back cleanly when the server rejects it.',check:'What event makes cached data stale, and who knows that event occurred?'},
  ssr:{model:'Rendering location is a per-route decision. HTML can be produced at request time, build time, or partly in the browser; hydration attaches behavior to matching markup.',example:'Marketing page: static. Account page: server-rendered. Rich editor: client-heavy island.',practice:'Classify five routes by freshness, personalization, SEO, interactivity, and operating cost.',check:'What causes a hydration mismatch and why can time-dependent rendering trigger one?'},
  testing:{model:'A test is an executable claim about observable behavior. Confidence comes from testing valuable boundaries, not maximizing test count.',example:'Given an expired session, when checkout loads, then the user is sent to sign-in and their cart remains.',practice:'Write one pure unit test, one integration test at a network boundary, and one critical browser journey.',check:'Which refactor should be possible without changing this test?'},
  node:{model:'Node can serve many waiting connections because I/O completion is event-driven, but JavaScript on one event loop still runs one callback at a time.',example:'pipeline(readable, transform, writable) applies backpressure instead of buffering the whole file',practice:'Stream a large file through a transform and compare memory usage with readFile.',check:'Why does one CPU-heavy loop delay unrelated network responses in the same process?'},
  api:{model:'An API is a contract about resources, transitions, errors, and evolution. HTTP semantics make that contract predictable to clients and infrastructure.',example:'PUT /users/42 with the same body can be retried; POST /payments needs an idempotency key.',practice:'Specify one endpoint in OpenAPI including validation errors, pagination, authentication, and retry behavior.',check:'What promise does idempotency make, and what state must the server retain to honor it?'},
  realtime:{model:'Messages cross an unreliable boundary. Design delivery guarantees, ordering scope, deduplication, and reconnection before choosing a transport.',example:'Consumer records eventId in the same transaction as its effect; a redelivery becomes a no-op.',practice:'Design a reconnecting notification stream that cannot display the same notification twice.',check:'Why is “exactly once” usually an application-level outcome rather than a transport guarantee?'},
  sql:{model:'Tables represent facts; keys identify them; constraints protect truths. Queries describe a result while the optimizer chooses an access plan.',example:'FOREIGN KEY (team_id) REFERENCES teams(id) prevents an orphaned membership.',practice:'Model users, teams, memberships, and invitations with keys, uniqueness, and deletion behavior.',check:'Which invariant belongs in a database constraint rather than only application code?'},
  indexes:{model:'An index is an ordered auxiliary structure. It avoids scanning many rows when its leading columns match the query, but every write must maintain it.',example:'INDEX (tenant_id, created_at) supports WHERE tenant_id=? ORDER BY created_at',practice:'Run EXPLAIN before and after an index; compare estimated rows, actual rows, and execution time.',check:'Why may an index on (a,b) help a query on a but not a query only on b?'},
  transactions:{model:'A transaction creates an all-or-nothing state transition. Isolation determines which concurrent intermediate states operations may observe.',example:'UPDATE accounts SET balance=balance-10 WHERE id=1; UPDATE ...+10 WHERE id=2; COMMIT',practice:'Reproduce a lost update with two sessions, then prevent it using a lock or optimistic version column.',check:'Which business invariant must remain true if two requests execute simultaneously?'},
  auth:{model:'Authentication produces an identity; authorization evaluates that identity, the resource, the action, and context for every trusted operation.',example:'canEdit = document.ownerId===user.id || membership.role==="editor"',practice:'Create an authorization matrix for guest, member, editor, and owner across five resources.',check:'Why is hiding a button never sufficient authorization?'},
  oauth:{model:'OAuth lets a client obtain limited API authority without learning the user password. OIDC adds signed identity claims about an authentication event.',example:'Browser → authorization endpoint + PKCE → callback with code → backend exchanges code for tokens',practice:'Draw the authorization-code flow and label browser-visible values, server-only values, and every validation.',check:'What attacks do state, nonce, redirect URI validation, and PKCE each mitigate?'},
  appsec:{model:'Security starts by mapping assets and trust boundaries, then asking how an attacker can violate confidentiality, integrity, or availability.',example:'Untrusted comment → HTML sink is an XSS path; user-supplied URL → internal fetch can become SSRF.',practice:'Threat-model one feature: diagram data flow, mark boundaries, list abuse cases, and assign mitigations.',check:'At which exact boundary does each piece of data become trusted, and based on what evidence?'},
  'browser-sec':{model:'Browser isolation is default-deny. CORS grants selected origins permission to read responses; CSP limits executable sources if injection occurs.',example:"Content-Security-Policy: script-src 'nonce-random' 'strict-dynamic'; object-src 'none'",practice:'Deploy a report-only CSP, inspect violations, then remove unsafe inline script dependencies.',check:'Why can a request succeed on the server while browser JavaScript is still forbidden to read it?'},
  secrets:{model:'Encryption protects recoverable data with a key; hashing creates a one-way digest; password hashing intentionally adds cost and unique salts.',example:'Store passwordHash=Argon2id(password, randomSalt); compare using the library verifier.',practice:'Inventory every secret in a sample service, its owner, scope, storage, rotation, and revocation path.',check:'Why is a fast general-purpose hash unsuitable for password storage?'},
  ci:{model:'A delivery pipeline is a deterministic proof chain from reviewed source to one immutable artifact and its deployment record.',example:'typecheck → tests → build image once → scan → deploy same digest → smoke test',practice:'Add a failing quality gate, observe the blocked release, then restore it and verify artifact identity.',check:'Why is rebuilding separately for production weaker than promoting the tested artifact?'},
  observability:{model:'Telemetry answers different questions: metrics reveal change, traces locate time across boundaries, and logs provide event detail.',example:'Attach trace_id, request_id, user-safe tenant ID, operation, duration, and outcome to structured logs.',practice:'Trace one request through UI, API, database, and queue; make one injected failure explainable.',check:'What user-visible question does each signal answer that the others cannot?'},
  reliability:{model:'Reliability is a measured product promise. An SLO defines acceptable outcomes; its error budget makes the speed-versus-stability trade-off explicit.',example:'99.9% successful checkouts over 28 days leaves about 40 minutes of equivalent total failure.',practice:'Define one SLI from the user perspective, choose an SLO, and write alerts for fast and slow budget burn.',check:'Why is 100% reliability usually an economically harmful target?'},
  architecture:{model:'A boundary is valuable when change on one side does not force unrelated change on the other. Good architecture preserves options around expensive decisions.',example:'Checkout depends on a PaymentPort; Stripe is one adapter, not a type used throughout the domain.',practice:'Map a system by capabilities and data ownership, then identify one dependency pointing in the wrong direction.',check:'Which current decision would be most expensive to reverse, and what evidence justifies locking it in?'},
  distributed:{model:'Remote calls are not function calls: they add latency, independent failure, duplication, reordering, and uncertainty about whether work happened.',example:'Client times out after payment succeeds; retry with the same idempotency key returns the original result.',practice:'For one cross-service operation, specify deadlines, retry ownership, idempotency, and reconciliation.',check:'After a timeout, how can the caller distinguish “failed” from “succeeded but response was lost”?'},
  leadership:{model:'Technical leadership creates leverage by improving decisions, interfaces, feedback loops, and the ability of others to own outcomes.',example:'An ADR records context, options, decision, consequences, owner, and a date to revisit assumptions.',practice:'Write a one-page decision memo with three options and ask a teammate to challenge its assumptions.',check:'Did your intervention increase team capability, or merely make the team depend on you?'}
};
window.ATLAS = { LEVELS, CATEGORIES, S, NODES, PATHS, STUDY };
